#!/usr/bin/env bash
# Tiny Town plates v2: realistic Klang Valley tilt-shift aerials (user, 13 Oct 2026: "more realistic in a Malaysia Klang Valley").
# Each run: Codex imagegen, then copy the newest PNG from that session into ./<name>.png
cd "$(dirname "$0")"
STYLE='Photorealistic tilt-shift aerial photograph (real camera, miniature-faking tilt-shift lens blur at top and bottom, slightly boosted saturation), shot in the Klang Valley, Malaysia. It must look like a real place in Cheras / Petaling Jaya / Puchong: rows of double-storey terrace link houses with orange-brown clay tile roofs, white walls, metal window grilles, car porches with gates, a concrete monsoon drain, Malaysian-style three-storey shoplots with five-foot ways, rain trees and palm trees, motorcycles and Malaysian cars (Perodua Myvi, Proton). Malaysian preschools (tadika / taska) are converted corner terrace houses or bungalows with colourful painted walls, a small playground and shade sails. Absolutely no readable text, letters, signboards with writing, number plates or logos anywhere (blur or leave signboards blank). 9:16 PORTRAIT (vertical phone format), 1080x1920 framing, premium commercial quality. Do not create, copy or save any files yourself; just generate the image.'
gen() { # name, scene description
  codex exec -m gpt-6-sol --skip-git-repo-check "\$imagegen Generate one image. ${STYLE} Scene: $2" > "gen-$1.log" 2>&1
  sid=$(grep -h "session id" "gen-$1.log" | awk '{print $3}')
  src=$(ls -t "$HOME/.codex/generated_images/$sid/"*.png 2>/dev/null | head -1)
  [ -n "$src" ] && cp "$src" "$1.png" && echo "done $1" || echo "FAILED $1"
}
gen v_town2 'Golden hour, wide high aerial view over a leafy Cheras residential neighbourhood: terrace rows curving along roads, two tadika in corner houses with playgrounds clearly visible in the mid-ground, a yellow Malaysian school van on the road, an LRT viaduct crossing in the distance, and the real Kuala Lumpur skyline on the horizon (Petronas Twin Towers, KL Tower, Merdeka 118). Composition: the KL skyline and warm hazy sky fill the top 30 percent (calm, for headline text); the neighbourhood with the two tadika fills the middle and bottom.' &
gen v_sprawl 'Late afternoon, very wide high aerial view showing the overwhelming scale of the Klang Valley: endless rows of near-identical terrace houses, condos and shoplots stretching to the hazy horizon in every direction, highways with flyovers threading through, no single focal point. Composition: the top 30 percent is hazy sky for headline text; the endless sprawl fills the rest.' &
gen v_school 'Golden hour, close low-angle tilt-shift view of one Malaysian tadika in a converted corner terrace house: brightly painted walls, a small colourful playground with a slide under a shade sail, a yellow school van parked at the gate, a rain tree, neighbours terrace houses beside it. The tadika sits in the lower half; the upper half is the softly out-of-focus street, trees and sky, calm for text and a UI card.' &
gen v_night 'Blue hour just after sunset, aerial tilt-shift view of the same kind of Cheras terrace neighbourhood: warm lights glowing in house windows, orange streetlights along the roads, car light trails on a highway, the KL skyline lit up on the horizon (Petronas Twin Towers, Merdeka 118). Calm and beautiful. The top 30 percent is dark blue sky with the skyline, calm for text.' &
gen v_office 'Morning, tilt-shift view looking down into a modern Kuala Lumpur office through a glass wall (like a dollhouse cutaway): a small Malaysian team at desks with monitors showing abstract colourful charts and graphs (no readable text), plants, a glass meeting room, the city outside the windows. The upper third is calmer and slightly out of focus for text.' &
gen v_top 'Golden hour, straight top-down drone view (orthographic, like a map) over a Puchong / Petaling Jaya neighbourhood: terrace roofs in rows, roads, a roundabout, a tadika with a playground, rain trees, parked cars, long soft shadows. No horizon.' &
wait
